use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        if s.len() < 2 {
            return Value::Bool(false);
        }
        let mut digits = s.chars().filter_map(|c| c.to_digit(10));
        let mut sum = 0;
        let mut is_second = false;
        while let Some(digit) = digits.next_back() {
            if is_second {
                sum += if digit * 2 > 9 { digit * 2 - 9 } else { digit * 2 };
            } else {
                sum += digit;
            }
            is_second = !is_second;
        }
        Value::Bool(sum % 10 == 0)
    } else {
        Value::Bool(false)
    }
}
